class Router {
  private final int limit;
  private final Deque<int[]> queue = new ArrayDeque<>();
  private final Set<String> seen = new HashSet<>();
  private final Map<Integer, List<Integer>> timesByDestination = new HashMap<>();
  private final Map<Integer, Integer> head = new HashMap<>();

  public Router(int memoryLimit) {
    limit = memoryLimit;
  }

  public boolean addPacket(int source, int destination, int timestamp) {
    String key = source + "," + destination + "," + timestamp;
    if (!seen.add(key)) return false;
    if (queue.size() == limit) forwardPacket();
    queue.add(new int[] {source, destination, timestamp});
    timesByDestination.computeIfAbsent(destination, d -> new ArrayList<>()).add(timestamp);
    return true;
  }

  public int[] forwardPacket() {
    if (queue.isEmpty()) return new int[0];
    int[] p = queue.poll();
    seen.remove(p[0] + "," + p[1] + "," + p[2]);
    head.merge(p[1], 1, Integer::sum); // the oldest packet is also the oldest for its destination
    return p;
  }

  public int getCount(int destination, int startTime, int endTime) {
    List<Integer> times = timesByDestination.get(destination);
    if (times == null) return 0;
    int from = head.getOrDefault(destination, 0);
    return lowerBound(times, endTime + 1, from) - lowerBound(times, startTime, from);
  }

  // first index >= from whose value is >= target
  private int lowerBound(List<Integer> times, int target, int from) {
    int lo = from, hi = times.size();
    while (lo < hi) {
      int mid = (lo + hi) >>> 1;
      if (times.get(mid) < target) lo = mid + 1;
      else hi = mid;
    }
    return lo;
  }
}

